{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 301,
  "params": {
    "name": "semantic_search",
    "arguments": {
      "_comment": "In production, replace query_text with the freshly streamed insight body. The Test script captures the top result into demo_insight_id for steps 2-4. label='Insight' searches the insight vector index.",
      "label": "Insight",
      "query_text": "Microsoft expanding Boston office footprint",
      "top_k": 3
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 302,
  "params": {
    "name": "find_matching_properties_for_insight",
    "arguments": {
      "_comment": "Returns properties matching the insight's market+asset_class, plus a ranked broker list. The Test script captures market + asset_class into collection variables for the next 2 steps.",
      "insight_id": "{{demo_insight_id}}"
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 303,
  "params": {
    "name": "recommend_broker_for_deal",
    "arguments": {
      "_comment": "Reuses market + asset_class captured from step 2. service_line is hardcoded but you can vary it (leasing, capital_markets, advisory).",
      "market": "{{insight_market}}",
      "asset_class": "{{insight_asset_class}}",
      "service_line": "leasing"
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 304,
  "params": {
    "name": "traverse_graph",
    "arguments": {
      "_comment": "Surface the SPOC team members already assigned to this client. start_label='Client' forces the Client node (not Tenant — they often share the same key but only Client carries SPOC_FOR edges). relationship_types limits to SPOC + service-line edges so governance is the only thing returned.",
      "start_node_id": "name::{{demo_client_name}}",
      "start_label": "Client",
      "max_hops": 1,
      "relationship_types": ["SPOC_FOR", "HAS_SERVICE_LINE", "BELONGS_TO"]
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 401,
  "params": {
    "name": "traverse_graph",
    "arguments": {
      "_comment": "Returns the broker's direct neighbors: Markets COVERED, AssetClasses SPECIALIZED_IN, Firm BELONGS_TO, Leases BROKERED_BY, Clients SPOC_FOR. ~5-15 nodes; never truncated.",
      "start_node_id": "email::{{demo_broker_email}}",
      "max_hops": 1
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 402,
  "params": {
    "name": "traverse_graph",
    "arguments": {
      "_comment": "Walk to deals + clients via 2 hops. target_labels keeps the dimensions that matter; without it AssetClass connects to ~5K Properties and the cap hits.",
      "start_node_id": "email::{{demo_broker_email}}",
      "max_hops": 2,
      "target_labels": ["Lease", "Property", "Tenant", "Client", "Pursuit", "Insight"]
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 403,
  "params": {
    "name": "traverse_graph",
    "arguments": {
      "_comment": "Top tenants (Microsoft, Amazon, Apple) have 350+ leases each — TENANT_IS would dominate. target_labels skips Lease so you see Insights/Pursuits/SPOCs instead.",
      "start_node_id": "name::{{demo_client_name}}",
      "max_hops": 1,
      "target_labels": ["Insight", "Pursuit", "Client", "Broker"]
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 404,
  "params": {
    "name": "traverse_graph",
    "arguments": {
      "_comment": "Walk pursuits + SPOC team members + parent service lines / firms. relationship_types restricts which edges to follow — TENANT_IS is excluded so leases don't dominate.",
      "start_node_id": "name::{{demo_client_name}}",
      "max_hops": 2,
      "relationship_types": ["FOR", "SPOC_FOR", "ASSIGNED_TO", "ABOUT", "BELONGS_TO", "HAS_SERVICE_LINE"]
    }
  }
}

{
  "jsonrpc": "2.0",
  "method": "tools/call",
  "id": 405,
  "params": {
    "name": "traverse_graph",
    "arguments": {
      "_comment": "Insight ABOUT edges to Market/Submarket/AssetClass/Tenant/Property. 1 hop is sufficient — insights have <10 ABOUT edges each.",
      "start_node_id": "{{demo_insight_id}}",
      "max_hops": 1
    }
  }
}
